<?php

namespace Tests\Unit;

use App\Exceptions\InvalidBoxCode;
use App\Support\BoxCode;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

/**
 * Checked against shared/box-code-vectors.json, which was generated by an
 * independent implementation; the mobile app runs the same vectors.
 */
class BoxCodeTest extends TestCase
{
    private static function vectors(): array
    {
        return json_decode(file_get_contents(dirname(__DIR__, 3).'/shared/box-code-vectors.json'), true);
    }

    public static function validCodes(): iterable
    {
        foreach (self::vectors()['valid'] as $v) {
            yield $v['code'] => [$v['device'], $v['sequence'], $v['code']];
        }
    }

    public static function invalidCodes(): iterable
    {
        foreach (self::vectors()['invalid'] as $v) {
            yield $v['input'].' ('.$v['reason'].')' => [$v['input'], $v['reason']];
        }
    }

    public static function normalizedCodes(): iterable
    {
        foreach (self::vectors()['normalize'] as $v) {
            yield $v['input'] => [$v['input'], $v['code']];
        }
    }

    public function test_alphabet_matches_the_shared_spec(): void
    {
        $this->assertSame(self::vectors()['alphabet'], BoxCode::ALPHABET);
        foreach (['O', 'I', 'S', 'B', 'Z'] as $confusable) {
            $this->assertStringNotContainsString($confusable, BoxCode::ALPHABET);
        }
    }

    #[DataProvider('validCodes')]
    public function test_generates_and_parses_valid_codes(string $device, int $sequence, string $code): void
    {
        $this->assertSame($code, BoxCode::make($device, $sequence)->value());

        $parsed = BoxCode::parse($code);
        $this->assertSame($device, $parsed->device);
        $this->assertSame($sequence, $parsed->sequence);
    }

    #[DataProvider('invalidCodes')]
    public function test_rejects_invalid_codes_with_the_right_reason(string $input, string $reason): void
    {
        try {
            BoxCode::parse($input);
            $this->fail("« {$input} » should have been rejected");
        } catch (InvalidBoxCode $e) {
            $this->assertSame($reason, $e->reason);
        }
    }

    #[DataProvider('normalizedCodes')]
    public function test_normalizes_typed_input(string $input, string $code): void
    {
        $this->assertSame($code, BoxCode::parse($input)->value());
    }

    public function test_make_rejects_out_of_range_values(): void
    {
        $this->expectException(InvalidBoxCode::class);
        BoxCode::make('A', 10000);
    }

    public function test_make_rejects_excluded_device_letters(): void
    {
        $this->expectException(InvalidBoxCode::class);
        BoxCode::make('O', 1);
    }
}
